script:
frappe.ui.form.on('Sales Invoice', {
    refresh(frm) {
        if (frm.doc.custom_fbr_status) {
            const status = frm.doc.custom_fbr_status;
            const indicator = status === 'Valid' ? 'green' : status === 'Invalid' ? 'red' : 'orange';
            frm.dashboard.add_indicator(__('FBR Status: {0}', [status]), indicator);
        }

        if (frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Post to FBR'), async () => {
                await post_invoice_to_fbr(frm, 'Sales Invoice');
            });
        }

        if (frm.doc.docstatus === 0 || frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Show FBR Payload'), async () => {
                if (frm.is_new()) {
                    frappe.msgprint(__('Please save the form first'));
                    return;
                }
                try {
                    const r = await frappe.call({
                        method: 'fbr_e_invoicing.api.build_fbr_payload.build_fbr_payload',
                        args: { sales_invoice_name: frm.doc.name },
                        freeze: true,
                        freeze_message: __('Building payload...')
                    });

                    if (r && r.message) {
                        const json = JSON.stringify(r.message.payload || r.message, null, 2);
                        const d = new frappe.ui.Dialog({
                            title: __('FBR Payload'),
                            size: 'large',
                            fields: [
                                {
                                    fieldtype: 'Code',
                                    fieldname: 'payload',
                                    options: 'JSON',
                                    read_only: 1,
                                    label: __('Payload'),
                                    height: 420
                                }
                            ],
                            primary_action_label: __('Copy to Clipboard'),
                            primary_action: () => {
                                const val = d.get_value('payload');
                                frappe.utils.copy_to_clipboard(val);
                                frappe.show_alert({ message: __('Copied!'), indicator: 'green' });
                            }
                        });
                        d.set_value('payload', json);
                        d.show();
                    }
                } catch (err) {
                    frappe.msgprint({
                        title: __('Error'),
                        indicator: 'red',
                        message: __(err?.message || 'Failed to build payload')
                    });
                }
            });
        }
    }
});

async function post_invoice_to_fbr(frm, doctype) {
    try {
        const r = await frappe.call({
            method: 'fbr_e_invoicing.api.fbr_queue.post_invoice_to_fbr',
            args: {
                doctype: doctype,
                docname: frm.doc.name,
            },
            freeze: true,
            freeze_message: __('Posting invoice to FBR...')
        });

        const response = r && r.message;
        if (!response) {
            frappe.show_alert({
                message: __('No response received from FBR system.'),
                indicator: 'orange'
            });
            return;
        }

        if (!response.success) {
            frappe.msgprint({
                title: __('Error'),
                indicator: 'red',
                message: __(response.error || 'Failed to post invoice to FBR.')
            });
            return;
        }

        let message = __('Invoice has been queued for FBR submission.');
        if (response.state === 'moved_to_processing') {
            message = __('Invoice is now being processed for FBR submission.');
        } else if (response.state === 'moved_to_pending') {
            message = __('Invoice is queued and will be processed after earlier pending items.');
        } else if (response.state === 'already_processing') {
            message = __('Invoice is already being processed by FBR.');
        } else if (response.state === 'already_submitted') {
            message = __('Invoice is already submitted to FBR.');
        }

        frappe.show_alert({ message, indicator: 'green' });
        frm.reload_doc();
    } catch (err) {
        frappe.msgprint({
            title: __('Error'),
            indicator: 'red',
            message: __(err?.message || 'Failed to post invoice to FBR.')
        });
    }
}

